from pathlib import Path
import json,base64
ROOT=Path(__file__).resolve().parents[1]
data={w:json.loads((ROOT/'characters'/w/'rig.json').read_text()) for w in ['hero','skeleton']}
imgs={p['file']:'data:image/png;base64,'+base64.b64encode((ROOT/p['file']).read_bytes()).decode() for d in data.values() for p in d['parts']}
template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tiny Legends — Motion Lab</title>
<style>*{box-sizing:border-box}body{margin:0;background:#17242c;color:#eae5da;font:16px system-ui,sans-serif}main{max-width:1060px;margin:auto;padding:30px 24px}header{display:flex;justify-content:space-between;align-items:center}h1{font-size:26px;margin:0}small{color:#9aaeb8}.tag{color:#89d6c0;font-size:12px;letter-spacing:2px}p{color:#b6c5ca;line-height:1.5}canvas{width:100%;background:#e9e4d8;display:block;border-radius:14px;box-shadow:0 12px 40px #0004}section{margin-top:18px;display:flex;gap:9px;flex-wrap:wrap;align-items:center}button,select{background:#2b3f49;color:#eae5da;border:1px solid #49616b;border-radius:8px;padding:11px 16px;cursor:pointer;font:inherit}button:hover{background:#3c5660}button.active{background:#2c7464;border-color:#6ed2b3}label{display:flex;align-items:center;gap:8px;padding:8px}input{accent-color:#6ed2b3}footer{margin-top:20px;font-size:13px;color:#91a6af}#status{font-size:13px;color:#8fd4c0}#stage.phone{max-width:430px;margin:auto}#stage.phone canvas{aspect-ratio:720/760;object-fit:contain}</style>
<main><header><div><div class="tag">TINY LEGENDS · ART & MOTION</div><h1>Meet the adventurer. And the problem.</h1></div><small>Character pack · v0.1</small></header><p>Two articulated 2D characters. Try a sword attack, interrupt it with a hit, or inspect the joints.</p><div id="stage"><canvas id="c" width="1000" height="500" aria-label="Animated hero and skeleton preview"></canvas></div><section>
<button id="idle">Idle</button><button id="heroAttack">Hero attack</button><button id="enemyAttack">Skeleton attack</button><button id="hit">Both take damage</button><button id="auto" class="active">Auto fight: on</button></section><section><label><input id="armor" type="checkbox">Alternate armour</label><label><input id="joints" type="checkbox">Show joints</label><label><input id="phone" type="checkbox">Phone-size preview</label><label>Speed <select id="speed"><option value="0.5">0.5×</option><option selected value="1">1×</option><option value="1.5">1.5×</option></select></label><span id="status">Loading artwork…</span></section><footer>Preview uses the same joint data and animation keys as the included Godot scenes. Equipment is attached to the moving joints. This is a first cutout animation pass.</footer></main>
<script>
const DATA=__DATA__,SOURCES=__IMAGES__,images={};const c=document.querySelector('#c'),ctx=c.getContext('2d');
const actors=[{who:'hero',x:355,face:1,a:'idle',t:0,impact:false},{who:'skeleton',x:645,face:-1,a:'idle',t:0,impact:false}];let auto=true,next=.9,turn=0,last=0,ready=false;
function sample(keys,t){for(let i=0;i<keys.length-1;i++){let [a,av]=keys[i],[b,bv]=keys[i+1];if(t<=b){let q=Math.max(0,Math.min(1,(t-a)/(b-a)));return Array.isArray(av)?av.map((v,j)=>v+(bv[j]-v)*q):av+(bv-av)*q;}}return keys.at(-1)[1];}
function mul(a,b){return[a[0]*b[0]+a[2]*b[1],a[1]*b[0]+a[3]*b[1],a[0]*b[2]+a[2]*b[3],a[1]*b[2]+a[3]*b[3],a[0]*b[4]+a[2]*b[5]+a[4],a[1]*b[4]+a[3]*b[5]+a[5]];}
function pose(d,act,t){let an=d.animations[act],n=Object.fromEntries(d.nodes.map(x=>[x.name,{...x}]));t=an.loop?t%an.duration:Math.min(t,an.duration);for(const tr of an.tracks)n[tr.node][tr.property]=sample(tr.keys,t);let m={};for(const v of Object.values(n)){let [x,y]=v.position,co=Math.cos(v.rotation),si=Math.sin(v.rotation),q=[co,si,-si,co,x,y];m[v.name]=v.parent?mul(m[v.parent],q):q;}return m;}
function action(i,a){actors[i].a=a;actors[i].t=0;actors[i].impact=false;document.querySelector('#status').textContent=`${actors[i].who}: ${a}`;}
function setAuto(v){auto=v;document.querySelector('#auto').classList.toggle('active',v);document.querySelector('#auto').textContent='Auto fight: '+(v?'on':'off');}
document.querySelector('#idle').onclick=()=>{setAuto(false);actors.forEach((_,i)=>action(i,'idle'));};
document.querySelector('#heroAttack').onclick=()=>{setAuto(false);action(0,'attack');};document.querySelector('#enemyAttack').onclick=()=>{setAuto(false);action(1,'attack');};document.querySelector('#hit').onclick=()=>{setAuto(false);actors.forEach((_,i)=>action(i,'hit'));};document.querySelector('#auto').onclick=()=>{setAuto(!auto);next=.1;};document.querySelector('#phone').onchange=e=>document.querySelector('#stage').classList.toggle('phone',e.target.checked);
function paintActor(ac){let d=DATA[ac.who],m=pose(d,ac.a,ac.t),world=[ac.face*1.15,0,0,1.15,ac.x,420];for(const p of [...d.parts].sort((a,b)=>a.z-b.z)){let vis=p.visible??true;if(['helmet','chestplate'].includes(p.name))vis=document.querySelector('#armor').checked && p.equipment_enabled!==false;if(!vis)continue;let mat=mul(world,m[p.node]);ctx.save();ctx.setTransform(...mat);let [w,h]=p.size,[px,py]=p.pivot;ctx.drawImage(images[p.file],-px*w,-py*h,w,h);ctx.restore();}if(document.querySelector('#joints').checked){ctx.save();ctx.lineWidth=1;ctx.strokeStyle='#03b8a0';ctx.fillStyle='#ff5570';for(const n of d.nodes){let q=mul(world,m[n.name]);if(n.parent){let p=mul(world,m[n.parent]);ctx.beginPath();ctx.moveTo(p[4],p[5]);ctx.lineTo(q[4],q[5]);ctx.stroke();}ctx.beginPath();ctx.arc(q[4],q[5],3,0,Math.PI*2);ctx.fill();}ctx.restore();}}
function draw(now){requestAnimationFrame(draw);if(!ready)return;let dt=Math.min(.05,(now-last)/1000||0)*+document.querySelector('#speed').value;last=now;if(auto){next-=dt;if(next<=0){action(turn,'attack');turn=1-turn;next=1.35;}}for(let i=0;i<2;i++){let ac=actors[i],an=DATA[ac.who].animations[ac.a];ac.t+=dt;if(ac.a==='attack'&&!ac.impact&&ac.t>=an.impact){ac.impact=true;action(1-i,'hit');}if(!an.loop&&ac.t>=an.duration){ac.a='idle';ac.t=0;}}
ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#e9e4d8';ctx.fillRect(0,0,1000,500);ctx.fillStyle='#d9d0bd';ctx.fillRect(0,420,1000,80);ctx.fillStyle='#b7ad9d';for(const ac of actors){ctx.beginPath();ctx.ellipse(ac.x,420,65,10,0,0,Math.PI*2);ctx.fill();}for(const ac of actors)paintActor(ac);ctx.font='13px system-ui';ctx.fillStyle='#50646f';ctx.fillText('ADVENTURER',285,469);ctx.fillText('SKELETON',610,469);}
Promise.all(Object.entries(SOURCES).map(([key,src])=>new Promise((resolve,reject)=>{let im=new Image();im.onload=()=>{images[key]=im;resolve();};im.onerror=reject;im.src=src;}))).then(()=>{ready=true;last=performance.now();document.querySelector('#status').textContent='Ready';}).catch(()=>document.querySelector('#status').textContent='Unable to load artwork');requestAnimationFrame(draw);
</script></html>'''
(ROOT/'previews'/'motion_lab.html').write_text(template.replace('__DATA__',json.dumps(data)).replace('__IMAGES__',json.dumps(imgs)))
print('Built portable interactive preview')
